from itertools import product

def gaussian_elimination(A):
    m, n = len(A), len(A[0])
    rank = 0
    for j in range(n):
        i_max = rank
        for i in range(rank, m):
            if abs(A[i][j]) > abs(A[i_max][j]):
                i_max = i
        A[rank], A[i_max] = A[i_max], A[rank]
        if A[rank][j] != 0:
            factor = 1 / A[rank][j]
            for j2 in range(n):
                A[rank][j2] *= factor
            for i in range(m):
                if i != rank:
                    factor = A[i][j]
                    for j2 in range(n):
                        A[i][j2] -= factor * A[rank][j2]
            rank += 1
    return rank

def matrix_multiplication(A, B):
    m, n, p = len(A), len(B), len(B[0])
    C = [[0 for _ in range(p)] for _ in range(m)]
    for i in range(m):
        for j in range(n):
            for k in range(p):
                C[i][k] += A[i][j] * B[j][k]
    return C

def compute_disc(D, M):
    ℓ = len(M)
    disc = float('inf')
    for coloring in product([-1, 1], repeat=ℓ):
        y = [sum(M[i][j] * coloring[j] for j in range(ℓ)) for i in range(len(D))]
        disc = min(disc, max(abs(y)))
    return disc

def compute_as(f):
    a = len(f)
    count = 0
    for x in product([0, 1], repeat=a):
        for y in product([0, 1], repeat=a):
            if x != y and f(x) == f(y):
                count += 1
    return count / (2 ** a)

def compute_beta(NW_D_f, m):
    n = len(NW_D_f)
