        pr_s = sum(NW_D_f(s) == 1 for s in product([0, 1], repeat=len(NW_D_f))) / (2 ** len(NW_D_f))
        pr_y = sum(T[y].count(1) / (2 ** y.count(1)) for y in product([0, 1], repeat=n)) / (2 ** n)
        beta = max(beta, abs(pr_s - pr_y))
